import {validLayerCount,ensureMapLayer} from '../map-layers.js';
import {spotlightErrors} from '../light-sources.js';
import {shiftPatrol,patrolMapErrors} from '../character-patrol.js';
import {foliageErrors,extractFoliage,placeFoliage} from '../foliage-data.js';
import {breachErrors,extractBreaches,placeBreaches,clearBlockBreaches} from '../breach-data.js';
import {extractLand,placeLand,landErrors} from '../land-paint.js';
import {canopyCells,canopyErrors} from '../editor-canopies.js';
import {copyBlockCharacters,mergeCharacterResources} from '../character-properties.js';
import {connectionSet} from './connections.js';
import {LEVELS,blankMap,validateMap,terrainAt,setTerrain,edgeKey,edgeCells,tileKey,roofTop} from './maps.js';
import {propCells,GROUNDS} from './environment.js';
export const isBlock=d=>d?.kind==='red-shift-block';
const inside=(p,x,y)=>p.x>=x&&p.x<x+24&&p.y>=y&&p.y<y+24;
const shift=(p,x,y)=>({...p,x:p.x+x,y:p.y+y,...p.patrol&&{patrol:shiftPatrol(p.patrol,x,y)}});
export function blockCanvas(name='Untitled block'){const m=blankMap(name);m.starts=[{x:230,y:230,z:0},{x:231,y:230,z:0},{x:230,y:231,z:0},{x:231,y:231,z:0}];m.exits=[{x:232,y:230,z:0}];return m;}
export function extractBlock(m,sx=0,sy=0){if(!Number.isInteger(sx)||!Number.isInteger(sy)||sx<0||sx>9||sy<0||sy>9)throw Error('Choose a sector from1 to10.');const x=sx*24,y=sy*24;
 for(const p of m.canopies||[])if(canopyCells(p).some(q=>inside(q,x,y))&&!canopyCells(p).every(q=>inside(q,x,y)))throw Error('A decorative roof crosses this block boundary.');for(const p of m.props||[]){const cells=propCells(p);if(cells.some(q=>inside(q,x,y))&&!cells.every(q=>inside(q,x,y)))throw Error('A prop crosses this sector boundary. Move it fully inside or outside first.');}
 for(const p of m.climbs||[])if(inside(p,x,y)!==inside(roofTop(p),x,y))throw Error('A roof climb crosses this sector boundary.');
 const d={...extractFoliage(m,x,y),...extractBreaches(m,x,y),...extractLand(m,x,y),...(m.canopies?{canopies:m.canopies.filter(p=>inside(p,x,y)).map(p=>shift(p,-x,-y))}:{}),kind:'red-shift-block',version:1,size:24,levels:m.levels,name:m.name,terrain:Array.from({length:24},(_,dy)=>Array.from({length:24},(_,dx)=>terrainAt(m,x+dx,y+dy))),upper:Array.from({length:m.levels-1},()=>({})),edges:{},props:(m.props||[]).filter(p=>inside(p,x,y)).map(p=>shift(p,-x,-y)),stairs:m.stairs.filter(p=>inside(p,x,y)).map(p=>shift(p,-x,-y)),climbs:(m.climbs||[]).filter(p=>inside(p,x,y)).map(p=>shift(p,-x,-y)),guards:m.guards.filter(p=>inside(p,x,y)).map(p=>shift(p,-x,-y))};
 for(let z=1;z<m.levels;z++)for(let dy=0;dy<24;dy++)for(let dx=0;dx<24;dx++){const t=m.upper?.[z-1]?.[tileKey(x+dx,y+dy)]||'void';if(t!=='void')d.upper[z-1][tileKey(dx,dy)]=t;}
 for(const [k,v]of Object.entries(m.edges)){const cells=edgeCells(k);if(cells.some(p=>inside(p,x,y))){const [axis,xs,ys,zs]=k.split(':');d.edges[edgeKey(axis,Number(xs)-x,Number(ys)-y,Number(zs||0))]=v;}}if(m.edgeLocks){d.edgeLocks={};for(const [key,value]of Object.entries(m.edgeLocks)){const [axis,a,b,z]=key.split(':');const local=edgeKey(axis,Number(a)-x,Number(b)-y,Number(z||0));if(d.edges[local])d.edgeLocks[local]=value;}}if(m.blockConnections?.[sx+','+sy])d.connections=structuredClone(m.blockConnections[sx+','+sy]);if(m.characterResources)d.characterResources=structuredClone(m.characterResources);if(m.dialogueDefinitions)d.dialogueDefinitions=structuredClone(m.dialogueDefinitions);return d;
}
export function applyData(m,d,x,y,remap=false){if(d.levels>m.levels)ensureMapLayer(m,d.levels-1);if(remap)d=copyBlockCharacters(d,m);mergeCharacterResources(m,d);placeLand(m,d,x,y);placeBreaches(m,d,x,y);if(m.canopies||d.canopies)m.canopies=[...(m.canopies||[]),...(d.canopies||[]).map(p=>shift(p,x,y))];for(let dy=0;dy<24;dy++)for(let dx=0;dx<24;dx++){setTerrain(m,x+dx,y+dy,0,d.terrain[dy][dx]);for(let z=1;z<LEVELS;z++)setTerrain(m,x+dx,y+dy,z,d.upper[z-1]?.[tileKey(dx,dy)]||'void');}
 placeFoliage(m,d,x,y);if(d.edgeLocks){m.edgeLocks||={};for(const [key,value]of Object.entries(d.edgeLocks)){const [axis,a,b,z]=key.split(':');m.edgeLocks[edgeKey(axis,Number(a)+x,Number(b)+y,Number(z||0))]=value;}}for(const [k,v]of Object.entries(d.edges)){const [a,b,c,z]=k.split(':');m.edges[edgeKey(a,Number(b)+x,Number(c)+y,Number(z||0))]=v;}
 for(const field of ['props','stairs','climbs','guards'])m[field]=[...(m[field]||[]),...d[field].map(p=>shift(p,x,y))];}
export function validateBlock(d){if(!isBlock(d)||d.version!==1||d.size!==24||!validLayerCount(d.levels))throw Error('Expected a 24 × 24 block with 3–6 layers.');if(!Array.isArray(d.terrain)||d.terrain.length!==24||d.terrain.some(r=>!Array.isArray(r)||r.length!==24))throw Error('Invalid block ground.');if(!Array.isArray(d.upper)||d.upper.length!==d.levels-1||d.upper.some(v=>!v||typeof v!=='object'||Array.isArray(v)))throw Error('Invalid block upper floors.');for(const field of ['props','stairs','climbs','guards'])if(!Array.isArray(d[field])||d[field].some(p=>!p||!Number.isInteger(p.x)||!Number.isInteger(p.y)||!inside(p,0,0)))throw Error('Invalid block '+field);if(!d.edges||typeof d.edges!=='object'||Array.isArray(d.edges))throw Error('Invalid block edges.');
 for(const layer of d.upper)for(const k of Object.keys(layer)){if(!['yard','floor','crate','bridge','woodland','woodland-dense',...GROUNDS].includes(layer[k]))throw Error('Invalid upper floor terrain.');const [x,y]=k.split(',').map(Number);if(k!==tileKey(x,y)||!Number.isInteger(x)||!Number.isInteger(y)||!inside({x,y},0,0))throw Error('Upper floor extends beyond block.');}
 for(const k of Object.keys(d.edges)){const [axis,x,y,z]=k.split(':');if(k!==edgeKey(axis,Number(x),Number(y),Number(z||0)))throw Error('Noncanonical block edge.');if(!/^(e|s):(-?\d+):(-?\d+)(?::[1-5])?$/.test(k)||!edgeCells(k).some(p=>inside(p,0,0)))throw Error('Edge extends beyond block.');}
 if(d.props.some(p=>!propCells(p).every(q=>inside(q,0,0)))||d.climbs.some(p=>!inside(roofTop(p),0,0)))throw Error('An object crosses the block boundary.');
 const spotlightIssues=spotlightErrors(d,null);if(spotlightIssues.length)throw Error(spotlightIssues[0]);const patrolIssues=patrolMapErrors(d,24);if(patrolIssues.length)throw Error(patrolIssues[0]);const foliageIssues=foliageErrors(d,24);if(foliageIssues.length)throw Error(foliageIssues[0]);const breachIssues=breachErrors(d,24);if(breachIssues.length)throw Error(breachIssues[0]);const landIssues=landErrors(d,24,GROUNDS);if(landIssues.length)throw Error(landIssues[0]);const roofErrors=canopyErrors(d,24);if(roofErrors.length)throw Error(roofErrors[0]);const m=blockCanvas(d.name);applyData(m,d,0,0);if(d.connections!==undefined)connectionSet(m,0,0,d.connections);const errors=validateMap(m,{connectivity:false});if(errors.length)throw Error(errors[0]);return d;
}
export function openBlock(d){validateBlock(d);const m=blockCanvas(d.name);applyData(m,d,0,0);if(d.connections)m.blockConnections={'0,0':structuredClone(d.connections)};return m;}
export function placeBlock(m,d,sx,sy){validateBlock(d);if(!Number.isInteger(sx)||!Number.isInteger(sy)||sx<0||sx>9||sy<0||sy>9)throw Error('Choose a sector from1 to10.');const x=sx*24,y=sy*24;
 for(const p of m.props||[])if(propCells(p).some(q=>inside(q,x,y))&&!propCells(p).every(q=>inside(q,x,y)))throw Error('An existing prop crosses the destination boundary.');
 for(const p of m.climbs||[])if(inside(p,x,y)!==inside(roofTop(p),x,y))throw Error('An existing climb crosses the destination boundary.');
 const retained={};for(const [k,v]of Object.entries(m.edges)){const cells=edgeCells(k);if(!cells.some(p=>inside(p,x,y)))continue;const external=cells.find(p=>!inside(p,x,y));if(external&&m.blockConnections?.[Math.floor(external.x/24)+','+Math.floor(external.y/24)]){const [a,b,c,z]=k.split(':'),local=edgeKey(a,Number(b)-x,Number(c)-y,Number(z||0));if(d.edges[local]!==undefined&&d.edges[local]!==v)throw Error('Shared boundary materials conflict with the neighboring block.');if(d.edges[local]!==undefined&&(d.edgeLocks?.[local]||0)!==(m.edgeLocks?.[k]||0))throw Error('Shared door lock conflicts with the neighboring block.');retained[k]=v;}}
 for(const p of m.canopies||[])if(canopyCells(p).some(q=>inside(q,x,y))&&!canopyCells(p).every(q=>inside(q,x,y)))throw Error('A decorative roof crosses the destination block.');const out=structuredClone(m);clearBlockBreaches(out,x,y);if(out.canopies)out.canopies=out.canopies.filter(p=>!inside(p,x,y));if(out.edgeLocks)for(const key of Object.keys(out.edgeLocks))if(edgeCells(key).some(p=>inside(p,x,y)))delete out.edgeLocks[key];for(const k of Object.keys(out.edges))if(edgeCells(k).some(p=>inside(p,x,y)))delete out.edges[k];for(const field of ['props','stairs','climbs','guards'])out[field]=(out[field]||[]).filter(p=>!inside(p,x,y));applyData(out,d,x,y,true);Object.assign(out.edges,retained);for(const key of Object.keys(retained))if(m.edgeLocks?.[key]){out.edgeLocks||={};out.edgeLocks[key]=m.edgeLocks[key];}out.blockConnections={...out.blockConnections};if(d.connections)out.blockConnections[sx+','+sy]=structuredClone(d.connections);else delete out.blockConnections[sx+','+sy];const errors=validateMap(out,{connectivity:false});if(errors.length)throw Error(errors[0]);return out;
}
